INSERT INTO `cb_textads` (`id`, `username`, `title`, `text`, `url`, `urlto`, `clicks`, `views`) VALUES
(1, 'wespac59', 'Sick of Money Scams?', 'You will NOT get rich, but you can make $500 per week.  This internet millionaire will help you make money!', '', 'https://9541epgev1p-gn2pt4v4pkxb42.hop.clickbank.net', 27, 126),
(2, 'wespac59', 'The Cash Machine', 'Looking for a way to earn easy money online? Check out this atuomatic cash machine. Make money now.', '', 'https://13260upqvvhzlr8ow6l8qin9ro.hop.clickbank.net', 27, 96),
(3, 'wespac59', 'Best Work At Home Biz', 'The best way to earn money online.  Get ready to finally start making money.  No experience needed!!!', '', 'https://0a4f5glo15f4bn46cm4otdx-0k.hop.clickbank.net', 23, 113),
(4, 'wespac59', 'Easy Money Online', 'Learn from one of the best internet marketers in the business.  Make money with this simple money program.', '', 'https://d4c1dvrfuwhsju6t58yzln2r0p.hop.clickbank.net', 23, 103),
(8, 'wespac59', 'Make Money From Home', 'Work from home and set your own hours.  Even newbies are making money with this step-by-step business op.', '', 'https://9ff5arqhz9ryapf7vfse8u5lcn.hop.clickbank.net', 23, 112),
(9, 'wespac59', '$3,000+ Per Month!', 'All you need is a computer and 15 minutes per day.  Work from the comfort of your own home.  Start today.', '', 'https://739bcutjuwp1pk9m5coirbx06a.hop.clickbank.net', 19, 103),
(10, 'wespac59', 'Earn $2,000 Per Month', 'No B.S. here! This program is tested and proven to make you money. You do not have to be a guru to earn.', '', 'https://0565cuqew4dzbocyu4o-48geuw.hop.clickbank.net', 9, 99),
(11, 'wespac59', 'The Top 5 Money Makers', 'These opportunities are tested and proven to make you money. These are not Get Rich Quick schemes. These are money-making opportunities that will earn you money online.', '', 'https://c96dakfjt7qzev4olitf06qdot.hop.clickbank.net', 19, 112);
INSERT INTO `cb_vendors` (`cb_vendor_number`, `cb_image`, `cb_title`, `cb_description`, `cb_vendor_name`) VALUES
(1, 'http://ez-moneymaker.com/images/5minuteprofit.PNG', 'The Five Minute Profit Sites', 'NEW! CONTROVERSIAL Software Exploits $12.3 MILLION LOOPHOLE & Makes Us $519/DAY...Find Out How You Can Start Today In Under 5 MINUTES & 17 CLICKS...', 'highepcs'),
(3, 'http://ez-moneymaker.com/images/paidsocial-review.jpg', 'Paid Social Media Jobs', 'This Single Mother Makes Over $700 per Week Helping Businesses With Their Facebook and Twitter Accounts....... And Now You Can Too!\r\n', 'socialpaid'),
(18, 'http://www.ez-moneymaker.com/images/sup-aff-review.png', 'Super Affiliate System', 'NEW MONEY MAKING SYSTEM. A Genius Way to Make Money Online starting Today.  Follow This “Beginner Friendly” 3-Step Formula Webinar.\r\n', 'j1r2c'),
(2, 'http://ez-moneymaker.com/images/auto_chat_profits.PNG', 'Auto Chat Profits', 'NEW! WEIRD Robot Technology Siphons Us Up To $423.67 A DAY With Shocking Consistency...336 CONSECUTIVE DAYS OF PROFIT (And Counting)', 'insanebars'),
(19, 'http://www.ez-moneymaker.com/images/recession_profits.png', 'Recession Profit Secrets', 'See Why Real People Love Creating Serious Wealth At Home with Recession Profit Secrets!  Make More Money or Lose Everything\r\nYou MUST Decide TODAY!', 'recprofit'),
(7, 'http://www.ez-moneymaker.com/images/click-earners-review.png', 'Click Earners', '\r\nStart Working & Earning Online. Discover how to become an \'Online Assistant\' and get paid to do work from home on behalf of major companies.\r\n', 'clkearners'),
(4, 'http://ez-moneymaker.com/images/social-sales-rep.PNG', 'Social Sales Rep', 'Social media users urgently required.  Do You Use Social Media? Turn Your Skills Into Extra Cash Generate a Full-Time Income working from home.', 'socialsrep'),
(6, 'http://www.ez-moneymaker.com/images/12min-review.png', 'The 12 Minute Affiliate System', 'You have Just Stumbled Across a Brand New System.  It Currently Makes Me $78 - $922 Per Day & Does All Of The Selling For Me! This Video Shows You How!', 'easiest123'),
(5, 'http://ez-moneymaker.com/images/clickwealth-review.png', 'Click Wealth System', 'This will be the easiest way to make $1,000.  All you have to do is just: Copy, Paste and Profit.  Give Me 5 Minutes & I Will Show How You Can Generate Your First Paycheck', 'clickw');
