INSERT INTO `url_mail_schedule` (`id`, `subject`, `description`, `mail_type`, `user_status`, `assigned`, `delivered`, `status`, `s_time`) VALUES
(14, 'Test Bulk Mail', 'Hello,\r\n\r\nthis is to test bulk and to test\r\n\r\nhow the message\r\n\r\nis formatted', 'plain', 'all', 7, 7, '2', '2015-03-19 00:56:53'),
(15, 'Testing Account Delete Page', 'Testing Account Delete Page', 'plain', 'all', 9, 9, '2', '2015-03-20 19:36:08'),
(13, 'Thank you for joining', 'Hi,<br />\r\n&nbsp;&nbsp;Thank you for Joining MyCashBackTraffic.com.<br />\r\n<br />\r\nUse your referer  url to refer members into your downline. Each time a member in your downline purchases \r\ntraffic, you will earn 9999% of their purchases.\r\n<br />\r\nAgain, Thanks For Joining!.<br />\r\nRegards,<br />\r\nMyCashBackTraffic.com, Admin', 'plain', 'all', 3, 3, '2', '2015-03-17 09:46:20'),
(16, 'Test Bulk Mail With PHP 5.2 (Single php.ini)', 'Test Bulk Mail With PHP 5.2 (Single php.ini)', 'plain', 'all', 8, 8, '2', '2015-03-21 20:25:09'),
(17, 'Test Bulk Mail With PHP 5.4 (Single php.ini)', 'Test Bulk Mail With PHP 5.4 (Single php.ini)', 'plain', 'all', 8, 8, '2', '2015-03-21 21:04:04'),
(18, 'test bulk mail again', 'Test bulk mail again.', 'plain', 'all', 3, 3, '2', '2015-03-30 09:20:37'),
(19, '{FIRSTNAME}, Test Bulk Mail 1', '{FIRSTNAME}, Test Bulk Mail 1 and test\r\nto see if the\r\nhtml will\r\nshow in the \r\nbody of \r\nthe email', 'plain', 'all', 4, 4, '2', '2015-03-31 20:02:32'),
(20, '{FIRSTNAME}, E.arn Up to *$150.00 Per Hour', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. There\\\'s an exclusive new opportunity\r\nthat has just popped up online. This special opportunity \r\nis available by invite only.  A few people were picked and \r\nwe decided we would invite you as one of them.\r\n\r\nIn this opportunity you can earn an income from home using \r\nnothing but your computer.  There\\\'s no marketing to do, \r\nno experience necessary.\r\n\r\nAll you\\\'ve got to do is give your opinion by checking a couple \r\nof boxes and completing a couple of forms and you will be \r\ncompensated for your time.\r\n\r\nFor more details, cl.ick on the link below.\r\n<a href=\\\"http://www.wespacaffiliates.com/cb.html\\\">Cl.ick Here For Details</a>  \r\n\r\nTo Your Success,\r\n\r\nMike', 'plain', 'all', 4, 3, '1', '2015-04-02 00:54:34'),
(21, '{FIRSTNAME}, E.arn Up to *$150.00 Per Hour', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. There\\\'s an exclusive new opportunity\r\nthat has just popped up online. This special opportunity \r\nis available by invite only.  A few people were picked and \r\nwe decided we would invite you as one of them.\r\n\r\nIn this opportunity you can earn an income from home using \r\nnothing but your computer.  There\\\'s no marketing to do, \r\nno experience necessary.\r\n\r\nAll you\\\'ve got to do is give your opinion by checking a couple \r\nof boxes and completing a couple of forms and you will be \r\ncompensated for your time.\r\n\r\nFor more details, cl.ick on the link below.\r\n<a href=\\\"http://www.wespacaffiliates.com/cb.html\\\">Cl.ick Here For Details</a>  \r\n\r\nTo Your Success,\r\n\r\nMike', 'plain', 'all', 4, 4, '2', '2015-04-02 16:52:53'),
(22, '{FIRSTNAME}, Your $10.00 Sign Up Bonus', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here.  Just a short note to let you know we\r\njust added your $10.00 sign up bonus to your account.\r\nIt\\\'s just our way of saying THANKS for joining.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n{BASEURL}', 'plain', 'all', 4, 4, '2', '2015-04-26 02:22:31'),
(23, '{FIRSTNAME}, Get Up to $50.00 F.REE', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. We would like to make you an offer you\r\ncan\\\'t refuse.  If you purchase 1 unit, we will add $25.00\r\nto your account.  If you purchase 2 or more units, we\r\nwill add $50.00 to your account.\r\n\r\nOnce you make your purchase, we will add the money to\r\nyour account and send you a confirmation email.  So\r\ndon\\\'t delay.  This offer will end on Monday, 8 Feb.\r\nSo order now!\r\n\r\nTo Your Success,\r\n\r\nMike \r\nhttp://www.mycashbacktraffic.com', 'plain', 'all', 99, 99, '2', '2016-02-01 23:36:54'),
(24, '{FIRSTNAME}, Good News!  VERY IMPORTANT, Please Read', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. We have received a lot of emails from you\r\nguys stating that the cost of a traffic unit is too high.  After \r\ncareful consideration, we agree.  So we have decided to make the\r\nfollowing changes:\r\n\r\n1)  The cost of a traffic unit will be reduced from $50 per unit to \r\n$10 per unit.  Note:  You will now receive 100 visitor credits for \r\neach unit purchased.\r\n\r\n2)  One of the two pay requirements has changed.  Note:  The\r\nonly thing that changed here is the number of Active Units \r\nrequired for pay.  Since we reduced the cost of a traffic unit, \r\nwe have increase the number of Active Units required for pay to 3.\r\n\r\nSo below are the revised two pay requirements:\r\n\r\nPayday will always be the 20th of each month and payment\r\nwill be made on your Total Cash Earned. In order to get\r\npaid, you must meet the following two pay requirements on\r\npayday the 20th of the month: \r\n\r\n* You must have at least 3 Active Traffic Unit\r\n* And your Total Cash Earned must be at least $1.00\r\n\r\nIf you meet the two pay requirements on payday the 20th of\r\nthe month, you will get paid. If you do not meet the two pay\r\nrequirements, your Total Cash Earned will continue to carry\r\nover until you meet the two pay requirements on payday, the\r\n20th of the month. \r\n\r\nVERY IMPORTANT: Log into your account, click on the\r\n\\\"Profile\\\" link at the top of the page and make sure your\r\nPayza payment email address is valid and correct. If your\r\nPayza payment email address is missing, invalid or\r\nincorrect, we cannot pay you. \r\n\r\n3)  There are NO Changes to the unit expiration date.  Units\r\nwill still expire 30 days from the date of purchase.\r\n\r\nWe hope these changes will make it more affordable for you\r\nto participate in our program.  It would be a shame if you \r\nmissed out on this golden opportunity to finally make money online.\r\nIf you have any questions, please write us back.\r\n\r\nTo Your Success,\r\n\r\nMike \r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log into Your Account</a>', 'plain', 'all', 105, 105, '2', '2016-02-05 23:49:24'),
(25, '{FIRSTNAME}, The 2 Most Frequently Asked Questions', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. We get a lot of questions from you guys, which\r\nis good.  Below are 2 of the most frequently asked questions\r\nwith the answers.\r\n\r\n1)  Can I refer my family and friends?\r\n\r\nYes, you can refer anybody.  There are no restrictions on who\r\nyou can refer.\r\n\r\n2)  I don\\\'t have a website.   Do I need to add a website and assign\r\nvisitor credits to them in order to get paid.\r\n\r\nNo, you do NOT need a website or have to assign visitor credits to them\r\nin order to get paid.  Some people join just for the cash and some \r\npeople join for the traffic and cash.  It\\\'s your choice.\r\n\r\nWe will also add these questions to the F.A.Q. section of our site.\r\nIf you guys have any questions, feel free to write at anytime.  You\r\nare our members and we are here to serve you.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 171, 171, '2', '2016-02-16 17:32:38'),
(26, '{FIRSTNAME}, Good News.  Please Read', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. Just a short note to let you know that we\r\nhave increased the affiliate commissions rate to 5%.  Now\r\nis the time for you to build your down line.  We have members\r\nwho are buying 50 to 60 units at a time and their referrers\r\nare cashing in big time.\r\n\r\nUnder the \\\"Affiliates\\\" link in your member\\\'s area, we have\r\nadded some Free and Paid Traffic Resources.  These are good\r\ntraffic sources as we use them ourselves and we know that\r\nthey are effective.\r\n\r\nSo log into your account, click on the \\\"Affiliates\\\" link, get your\r\nreferral url and start making some serious cash\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 210, 211, '2', '2016-02-20 06:26:37'),
(27, '{FIRSTNAME}, We Just Added a New Feature', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. Just a short note to tell you\r\nabout the new feature we added.  You can now\r\npurchase Visitor Credits only.\r\n\r\nWe have 2 links in the members\\\' area.  When\r\nyou log into your account, scroll down to item#\r\n7 of the site and instructions and you will see\r\nthe first link.\r\n\r\nFor the second link, click on the \\\"Buy Units\\\"\r\nlink at the top of the page and the second link\r\nis just below the Traffic Unit purchase form.\r\n\r\nIf you have any questions, write us back.\r\n\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 262, 262, '2', '2016-02-21 21:29:42'),
(28, '{FIRSTNAME}, Here\\\'s How To Build a MASSIVE Downline Fast', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. Just a short note to tell you about\r\na wonderful program that can bring you referrals\r\nreally fast. Maryanne Myers is the owner of the site.\r\nShe\\\'s a respectable marketer and knows how to\r\ndeliver traffic.\r\n\r\nIf you are serious about building a solid income\r\nonline, you need to build your downline and you\r\nneed to check out her site.  So click on the link\r\nbelow and start building a MASSIVE downline\r\n\r\n<a href=\\\"http://1tae.com/wespac\\\">Cl.ick Here To Visit Site</a>\r\n\r\nIf you have any questions, write us back.\r\n\r\n\r\nTo Your Success,\r\n\r\nMike', 'plain', 'all', 259, 259, '2', '2016-02-22 08:35:36'),
(29, '{FIRSTNAME}, Our Pay System Explained', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. We are receiving a lot of emails regarding how\r\nour pay system works.  So the purpose of this email is to\r\nexplain how our pay system works:\r\n\r\n1)  Whenever you purchase a Traffic Unit, the unit will expire 30 days\r\nfrom the date of purchase.  You do NOT earn the 200%\r\ncash back until a unit expires.  Once a unit expires, you will earn\r\n200% of the purchase amount for that unit.  So each time a unit expires,\r\nyour Total Cash Earned will update to show the 200% cash back on\r\nthe units that just expired.\r\n\r\nFor example, let\\\'s say your Total Cash Earn is $0.00 and you\r\nhad 6 Active units and those 6 Active units expired today\r\n24 Feb.\r\n\r\nOnce those 6 units expire, your Total Cash Earned will update and show\r\na balance of $120.\r\n\r\n6 units @ $10 each = $60 purchase amount x 200%\r\ncash back rate = $120 Total Cash Earned.  \r\n\r\nSo at this point, you only meet one of the pay requirements,\r\n(Your Total Cash Earned IS at least $1).\r\n\r\nSince your 6 Active units expired, you now have 0 Active units.\r\n(Which means you DO NOT meet the other requirement of\r\nhaving at least 3 Active units).\r\n\r\nSo in order to get paid on pay day the 20th of Mar, you will need\r\nto purchase at least 3 more units before pay day, the 20th of Mar.\r\n\r\nNow let\\\'s say you purchase 5 units tomorrow, the 25th of Feb.\r\nYou would get paid on pay day the 20th of Mar because on the 20th\r\nof Mar, you would meet both pay requirements.  You would have 5\r\nActive units and your Total Cash Earned would be $120.\r\n\r\n2) The key to understanding our system is to know the status of your\r\nActive and Expired units.  And to better understand the status\r\nof your units, we recommend that you take a look at your Traffic\r\nUnit Purchase History.  Just click on the \\\"History\\\" link in your\r\nmember\\\'s area.\r\n\r\nAlways look to see how many Active units will you have on the\r\n20th of the month.  If you know you will have less than 3\r\nActive units on pay day the 20th of the month, then you know you\r\nwill need to purchase more units before pay day, the 20th of the month.\r\n\r\nThe Total Cash Earned requirement is easy to meet.  Once\r\na unit expires, your Total Cash Earned will definitely be at\r\nleast $1  \r\n\r\nTIP ==> To ensure you will always get paid on pay day the 20th of the month,\r\nyou could purchase at least 3 units as often as you can.  This does a couple\r\nof things.  You would always have at least 3 Active units at any given time\r\nand you will create a steady flow of income.  We noticed that some of\r\nour high earning members have deployed this strategy.\r\n\r\nI hope that things are a little bit clearer now.  So in conclusion, there are\r\ntwo things to remember.\r\n\r\n1)  Make sure you understand the 2 pay requirements    \r\n\r\n2)  Take a look at your Traffic Unit Purchase History and know how many Active\r\nunits you will have on pay day the 20th of the month.\r\n\r\nIt is so Important that all members understand how our pay system works.\r\nThere is no such thing as a stupid question. So if you have questions, please write us back.\r\n\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 301, 303, '2', '2016-02-24 20:48:19'),
(30, '{FIRSTNAME}, Another F.A.Q. Question Explained', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. It seems some of you guys are still confused\r\nabout the pay system.  We are getting the following questions:\r\n\r\n1)  Do I have to have exactly 3 Active Units on pay day in order\r\nto get paid?  \r\n\r\nYou DO NOT need Exactly 3 Active units on pay day\r\nin order to get paid.  As long as you have on pay day, the minimum number\r\nof Active Units, which is 3, you will meet the first pay requirement.\r\nAnd if your Total Cash Earned is at least $1, you will meet both pay\r\nrequirements and you will get paid.\r\n\r\n2)  What if I have more than 3 Active Units on pay day, will I still get\r\npaid?  \r\n\r\nYes, if you have more than 3 Active Units on pay day, you\r\nwill meet the first pay requirement and if your Total Cash Earned\r\nis at least $1, you will meet both pay requirements and you\r\nwill get paid.\r\n\r\nSo the bottom line is this.  If you have 3 or more Active Units on\r\npay day, the 20th of the month and your Total Cash Earned is at\r\nleast $1, you will get paid as you will meet both pay requirements on\r\npay day, the 20th of the month.\r\n\r\nI hope any questions you had about the two pay requirements\r\nare now answered.  If not, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 449, 449, '2', '2016-03-01 06:45:41'),
(31, '{FIRSTNAME}, Here\\\'s An Offer You Can\\\'t Refuse', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here.  We have one member who has over 200\r\nmembers in his down line.  Not only does he have a large\r\ndown line, but a lot of his down line members are buying \r\ntraffic units.  We noticed that each pay day, his affiliate \r\ncommissions were huge.\r\n\r\nSo we sent him an email to ask him what was he doing to\r\nbuild such a huge down line.  He wrote back and told us that\r\nhe was advertising on TrafficMonsoon.  Specifically, he purchases\r\nthe 5 seconds No Geo Targeted Cash Link.  Which is only $1\r\nper 500 clicks.\r\n\r\nSo our staff decided to test it by buying $50 worth of Cash\r\nLinks, which was 25,000 clicks and sure enough, we got quite\r\na few signup and quite a few of them purchased traffic units.\r\n\r\nWe ran the same test again just to make sure it wasn\\\'t a\r\nfluke and again great results.\r\n\r\nSo here is the offer I have for you.  If you purchase at\r\nleast $50 worth of Cash Links and you do not get at least\r\ntwo members that purchase traffic units, we will reimburse you the\r\namount of money you paid for the Cash Links.\r\n\r\nWe think this is a win - win situation.  You get to build\r\nyour down line and earn huge affiliate commissions and this\r\nmakes MyCashBackTraffic more solid and stronger.\r\n\r\nIf you decide to take us up on this offer and you do not get\r\nat least two members that purchase traffic units, just send\r\nus a copy of your Payza receipt and we will reimburse you for \r\nthe amount you spent.  \r\n\r\nRemember, you have to spend at least $50, which will give\r\nyou 25,000 clicks.  Also, make sure you advertise your\r\nMyCashBackTraffic referral url and make sure you purchase \r\nthe 5 seconds No Geo Targeted packs.\r\n\r\nIf you are not a member of TrafficMonsoon, please click on\r\nthe link below and join.  And if you have any questions,\r\nwrite us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"https://trafficmonsoon.com/?ref=wespac\\\">Cl.ick Here To Join TrafficMonsoon</a>', 'plain', 'all', 458, 458, '2', '2016-03-02 01:29:16'),
(32, '{FIRSTNAME}, 30,000 FREE Visitors Per Month?', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here.  Just a short note to tell you about WorldProfit.com\r\nThey have been around since 1994 and we have always enjoyed\r\nquality traffic from them.  Currently, they are offering 30,000+\r\nFree visitors per month.  That\\\'s not bad.\r\n\r\nBut what I\\\'m really excited about and what I really want to tell\r\nyou about is their Super Solo Package.  We get great results\r\nevery time we mail to their lists.\r\n\r\nThey have other great Free and Paid options, but the Super\r\nSolo Package is the best hands down.  So go ahead and\r\nclick on the link below.  It\\\'s free to join and a great way\r\nto build your down line on a tight budget.\r\n\r\nIf you have questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://soloemailblaster.com/?id=5539563\\\">Cl.ick Here To Visit WorldProfit.com</a>', 'plain', 'all', 605, 606, '2', '2016-03-06 16:56:13'),
(33, '{FIRSTNAME}, Need Another Way To Fund Your Payza Account?', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here.  Quite a few members have asked if we could\r\nadd another payment option.  At the moment, we are considering\r\nadding Solid Trust Pay.  But for now, you can fund your Payza\r\naccount using BitCoins.  To learn more about BitCoins, please\r\n<a href=\\\"https://www.bitcoin.com/\\\">Click Here</a>  \r\n\r\nBefore you can use BitCoins, you will need to join an exchange.\r\nThe best exchange for the United States is CoinBase.  \r\n<a href=\\\"https://www.coinbase.com/join/56d2a54c64a0153f4600049a\\\">Click Here To Join CoinBase</a>\r\n\r\nIf you are from a country other than the United States, just go to BitCoin.com,\r\nscroll down the page a little ways and click on \\\"Choose An Exchange\\\".\r\n\r\nSo here are the abbreviated steps to fund your Payza account using\r\nBitCoins.\r\n\r\n1)  Join Coin Base (if you are from the U.S.).  If you are not from the\r\nU.S., then join an exchange from your home country.\r\n\r\n2)  You will need to verify your email address and phone# with the\r\nexchange.  Once you have verified your email address and phone#, log into\r\nyour exchange account.\r\n\r\n3)  Choose what type of wallet you want (ie.. bank account, credit card)\r\nOnce you have added your bank account and or credit card, the exchange will\r\nverify that you are the owner of that account by depositing 2 small\r\namounts into the account you added.\r\n\r\nNOTE:  If you have an online banking or credit card account, you can\r\nimmediately log into that account and get the 2 small amounts the\r\nexchange deposited into your account.  This saves time as you do\r\nnot have to wait until you receive your bank or credit card statement\r\nin the mail in order to get the 2 small deposits.\r\n\r\n4)  Once you have funded your exchange account, log into your Payza\r\naccount, click on \\\"Add Funds\\\" and choose the BitCoin option.  You will\r\nneed to enter the amount you want to add to your Payza account\r\nin BitCoins.\r\n\r\nTo do this, Just go to the BitCoin money converter at:  \r\nhttps://tools.bitcoin.com/ enter the dollar amount you want to add\r\nto your Payza account and it will convert that dollar amount into a bit coin\r\namount. \r\n\r\nJust copy and paste the BitCoin amount into the \\\"Amount in BitCoins\\\"\r\nfield on the Payza form.  Click \\\"Next\\\", enter your Transaction Pin#, Click \\\"Deposit\\\" and\r\nyou\\\'re done.\r\n\r\nI know it sounds like a lot, but it really isn\\\'t.  Also, the money is\r\nimmediately deposited into your Payza account.  So if you ever\r\nneed another way to fund your Payza account, this would be\r\na great option.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your success,\r\n\r\nMike', 'plain', 'all', 750, 750, '2', '2016-03-13 13:44:44'),
(34, '{FIRSTNAME}, I Forgot to Add Step# 5', 'Hi {FIRSTNAME},\r\n\r\nI forgot to add Step# 5.  Below is Step# 5\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n\r\n\r\n\r\n5)  Once you click the \\\"Deposit\\\" button on the Payza form, you\\\'ll be taken to a\r\npage where you\\\'ll see \\\"Bitcoin Amount\\\" and \\\"Bitcoin Address\\\".  Log into\r\nyour exchange account and click on the Send/Request link.  There will be\r\na form to send funds to Payza.\r\n\r\nCopy and paste the Bitcoin address from the Payza page into the \\\"Recipient\\\" field\r\nof your exchange page.  Copy and paste the bitcoin amount from the\r\nPayza page into the \\\"Amount\\\" field of your exchange page.   Note:  To the\r\nright of the \\\"Amount\\\" field, make sure BTC is checked.\r\n\r\nThere\\\'s a section entitled \\\"Notes\\\".  You can write a short note.  But\r\nit\\\'s optional.  Next, click the \\\"Send Funds\\\" button and you\\\'re done!\r\n\r\nNOTE:  Once you click the \\\"Deposit\\\" button on the Payza form, the transaction must\r\nbe completed within 60 minutes.  If your Bitcoin deposit is not sent within 60 minutes,\r\nthe transaction will expire and be cancelled within your account. Deposits made after\r\nyour transaction expires will not be honored.', 'plain', 'all', 759, 759, '2', '2016-03-13 18:47:40'),
(35, '{FIRSTNAME}, You Have Got to See This!', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. You can now post your ad to thousands\r\nof REAL Facebook and Twitter users.  This program is extremely\r\npowerful and I think you\\\'re going to like this one.\r\n\r\nBut I\\\'m not going to hype it.  You should check it out\r\nfor yourself and then decide.  For more details, click on\r\nthe link below.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://wespac59.cashblurbs.hop.clickbank.net\\\">Click Here To Visit The Site</a>', 'plain', 'all', 1491, 1493, '2', '2016-03-26 22:17:52'),
(36, '{FIRSTNAME}, The \\\"Buy Units\\\" Link is Now Activated', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here. The \\\"Buy Units\\\" link is now activated\r\nand you can purchase Traffic Units now.  Sorry for the long\r\ndelay!  \r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 1585, 1587, '2', '2016-03-31 02:49:28'),
(37, '{FIRSTNAME}, Are You Still Confused About Our Pay System?', 'Hi {FIRSTNAME},\r\n\r\nMike here. We have members that are still confused\r\nabout our pay system.  So we have come up with a\r\ncondensed version of How Our Pay System Works.\r\n\r\nTo eliminate confusion, this condensed version focuses\r\non the most important points of our pay system.  So\r\ngo ahead and log into your account, scroll down to\r\nstep# 8, click on the link and you can read\r\nHow Our Pay System Works.\r\n\r\nOnce you have read it and you still have questions,\r\nwrite us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Cl.ick Here To Log Into Your Account</a>', 'plain', 'all', 1609, 1614, '2', '2016-03-31 23:09:52'),
(38, '{FIRSTNAME}, Info Regarding Text Ads', 'Hi {FIRSTNAME},\r\n\r\nMike here. We would like to ask members not to\r\nadd their MyCashBack referral url when adding\r\ntext ads.\r\n\r\nIt\\\'s not fair for members to have a text ad advertising\r\nMyCashBackTraffic on another member\\\'s page.\r\n\r\nAnd here is why.  Let\\\'s say a visitor visits User ID# 10942\r\npage, our system will place a cookie on the visitor\\\'s\r\ncomputer for User ID# 10942.  But if that visitor\r\nclicks on a text ad advertising MyCashBackTraffic,\r\nour system will place another cookie on the visitor\\\'s\r\ncomputer, thus overriding User ID# 10942 cookie.\r\n\r\nSo if the visitor signs up, User ID# 10942 would not\r\nget credit for that sign up.  The member whose text\r\nad was clicked on would get the credit.\r\n\r\nWe have already deleted text ads advertising\r\nMyCashBack and we should not have this problem\r\ngoing forward.\r\n\r\nNOTE:  Adding your MyCashBack referral url on the\r\n\\\"Site\\\" page is OK as the traffic is from a different\r\nsource and the problem mentioned above is not\r\nan issue.\r\n\r\nAlso, if you haven\\\'t added any text ads or you haven\\\'t\r\nadded the maximum of 5 text ads, you should do so\r\nnow.  Our site receives thousands of visitors each day\r\nand you are missing out on potential signups and sales\r\nfor your other programs.\r\n\r\nDon\\\'t forget, you can also add the same text ad 5 times.\r\nJust use different titles for each text ad.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 1778, 1778, '2', '2016-04-02 20:14:00'),
(39, '{FIRSTNAME}, Do Not Recognize a Charge on Your Credit Statement?', 'Hi {FIRSTNAME},\r\n\r\nMike here. Quite a few members have sent us emails stating that there\\\'s a \r\ncharge on their credit card statement that they do not recognize.  \r\nSo we wrote Payza and below is the response from Payza.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n\r\n======================================\r\nOn 4/8/2016 9:15 AM, Payza Customer Support wrote:\r\n======================================\r\n\r\n> Hi Mike,\r\n>\r\n> My name is Subhash, and let me start by thanking you for contacting us.\r\n>\r\n> We apologize for the delay in responding to your query. Please note that our\r\n Customer Support team is working diligently to provide the quickest and most \r\nefficient service possible. However, we are experiencing a high volume of emails \r\nwhich is affecting our response time. \r\n>\r\n> Please note that our credit card processor is located in China, therefore our \r\ncustomers bank statement will show details from china.\r\n>\r\n> If customers see this charge on their credit card statement, please note that it \r\ncorresponds with their Payza deposit/withdrawal. \r\n>\r\n> Customer\\\'s are also being notified by email for deposits made to their Payza \r\naccount by credit card.\r\n>\r\n> Thanks again for contacting us. If you have any other questions or problems in \r\nthe future, myself or one of my colleagues will be more than happy to help.\r\n>\r\n> Sincerely,\r\n>\r\n> Subhash S\r\n> Customer Support Advisor\r\n> Payza.com\r\n>\r\n>\r\n> Ticket Details\r\n> ---------------------------------\r\n> Ticket ID: GSD-907-76934\r\n> Subject: Possible Credit Card Fraud\r\n>\r\n>\r\n> Need more info? Search our FAQs for step-by-step instructions and detailed information: https://helpdesk.payza.com/index.php?\r\n>', 'plain', 'all', 2168, 2172, '2', '2016-04-09 13:09:41'),
(40, '{FIRSTNAME}, Changes To The Affiliate Commission Rate', 'Hi {FIRSTNAME},\r\n\r\nMike here. For the last few months, the affiliate commissions\r\nhave been 30% to 37% of the total payroll and this expense\r\nis way too high.  So effective immediately, the affiliate\r\ncommission rate will be reduced from 5% to 2%.\r\n\r\nNow you might think 2% is way too low, but don\\\'t forget,\r\nyou get 2% of the purchase amount.  Purchase amounts\r\nrange from $10 to $5,000.  So you can potentially earn\r\n$100 on just one sale.\r\n\r\nWe really did not want to do this.  But to maintain our\r\n6:1 Income to Debt ratio and to continue our solid\r\nfinancial foundation, we felt it was necessary.\r\n\r\nThis is a proactive move that benefits the company\r\nand you as a member.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2192, 2194, '2', '2016-04-10 00:12:25'),
(41, '{FIRSTNAME}, Understanding Our Pay System', 'Hi {FIRSTNAME},\r\n\r\nMike here. We have noticed that quite a few members\r\nhave a Total Cash Earned of at least $1.00, but\r\ncurrently have 0 Active units.  \r\n\r\nWe\\\'re not sure if they do not understand the pay\r\nsystem or they are waiting to purchase at least\r\n3 units before the 20th of the month.\r\n\r\nSo we would like to recommend you read \\\"How\r\nOur System Works\\\".  Just log into your MyCashBack\r\naccount, scroll down to step# 9, click on that link\r\nand you can read \\\"How Our Pay System Works\\\".\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2479, 2480, '2', '2016-04-15 09:18:40'),
(42, '{FIRSTNAME}, Need Another Option To Purchase Traffic Units?', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Several members have written us telling us they are having\r\nproblems funding their Payza account.  You now have the option of\r\npurchasing Traffic Units using Solid Trust Pay.\r\n\r\nIf you would like to purchase Traffic Units using Solid Trust Pay, please\r\ndo the following:  Log into your Solid Trust Pay account and send the money to:\r\n<font color=\\\"#2d607\\\"><b>wespac</b></font>  In the notes area, put the following:  \r\n(Your MyCashBack User ID# and the number of Traffic Units you are purchasing).\r\n\r\nIf you do not have a Solid Trust Pay account, <a href=\\\"https://www.solidtrustpay.com/ref/v21wka7u\\\" target=\\\"_blank\\\"><font color=\\\"#2d607\\\"><b>Click Here</b></font></a> to get one free.  Please allow at least 24 hours for us to manually process your order.  Also, please\r\nuse this option <b>ONLY</b> if you are having troubles funding your Payza account with your bank\r\naccount, credit card or bitcoins.  As all orders are manually processed and it would\r\ntake too much time to manually process hundreds of orders.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2646, 2647, '2', '2016-04-17 20:52:34'),
(43, '{FIRSTNAME}, I Left Out Some Important Info in My Last Email', 'Hi {FIRSTNAME},\r\n\r\nMike here. If you decide to use Solid Trust Pay, the minimum\r\npurchase is $50.00.  Any purchase less than $50.00 will be\r\nrefunded back to you.  Sorry we have to do this as it is too much\r\nwork to manually process a $10 order.\r\n \r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2687, 2689, '2', '2016-04-18 08:49:07'),
(44, '{FIRSTNAME}, About Visitor Credits With The Purchase of Traffic Units', 'Hi {FIRSTNAME},\r\n\r\nMike here. One of our major traffic suppliers has raised the cost of purchasing\r\ntheir traffic.  Due to this fact and the fact that not many members purchased\r\nvisitor credits anyway, we are no longer offering 100 visitor credits with\r\neach Traffic Unit purchased.\r\n\r\nThis is a hard decision to make as we enjoyed given you 100\r\nvisitor credits with each traffic unit purchased.  But don\\\'t worry, we\\\'ll find\r\nother things that we can give you that will benefit you and your business.\r\n\r\nAlso, do not take this as a sign that we are not financially sound.  This\r\nis a business and we need to watch our expenses.  We have been going\r\nstrong for over 2 years and we WILL be here for years to come.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2825, 2825, '2', '2016-04-19 22:13:11'),
(45, '{FIRSTNAME}, Is Your Payza Email Address Correct?', 'Hi {FIRSTNAME},\r\n\r\nMike here.  We have just completed payroll and for\r\nthe first time in months, Payza has rejected quite\r\na few payments.  The reason for the rejections\r\nwas mainly due to invalid email addresses.\r\n\r\nOther reasons for the rejections were:\r\n\r\n- Members could not receive payments from the\r\nU.S.\r\n\r\n- And members could not send or receive payments\r\nat the time we ran the payroll.  (I guess this is\r\nsome sort of account limitation Payza had imposed on\r\nthose members).\r\n\r\nWe would like to ask you to take the time now and\r\nlog into your MyCashBack account, click on the\r\n\\\"Profile\\\" link at top and make sure your Payza\r\nemail address is correct.\r\n\r\nIf you did not get paid and you met both pay\r\nrequirements and your Payza email address listed in\r\nyour MyCashBack account was correct, you will need\r\nto notify Payza and find out why your payment was\r\nrejected.\r\n\r\nFor the members whose payments were rejected,\r\nwe will add your payment back to your MyCashBack\r\naccount and that money will be payable on the\r\n20th of May providing you meet the 2 pay\r\nrequirements on the 20th of May.\r\n\r\nIf you have any questions, write us back.\r\n\r\nTo Your Success,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 2868, 2870, '2', '2016-04-20 08:50:35'),
(46, '{FIRSTNAME},  An Important Update', 'Hi {FIRSTNAME},\r\n\r\nMike here.  We have noticed an alarming trend that has us seriously concerned.  After\r\na lot of members are paid on the 20th of the month, they turn right around\r\nand immediately purchase a large number of Traffic Units.  We understand they\r\nare just trying to maximize their earnings for the following payday.\r\n\r\nUnfortunately, this puts a heavy burden on the payouts for the following\r\nmonth.  So in an effort to regulate the large volumes of Traffic Units\r\npurchased on the 20th of the month and to decrease the burden on next month\\\'s\r\npayroll, Traffic Units will not be sold on the 20th and 21st of each month.\r\n\r\nThese decisions were not easy decisions for us to make.  But in order\r\nto achieve our following goals:  \r\n\r\n1)  Ensure that MCBT is here for years to come\r\n\r\n2)  And ensure you are paid each and every month,\r\n\r\nthese decisions had to be made.  We have to think about the sustainability\r\nand longevity of the program.  I know some of you might just walk away and\r\ncall us scammers and some other choice words.  We understand that.  \r\n\r\nBut for those of you that will stick with us, MCBT WILL be here for years to\r\ncome and we WILL continue to pay you each and every month.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 4180, 4180, '2', '2016-05-20 08:55:55'),
(47, '{FIRSTNAME}, Server Issues & Migration', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sorry for the long downtime.  Our site was suppose\r\nto be moved to a different server at 10:00 A.M. Hawaii time.\r\nBefore they could move the site, the server that our site was\r\non encountered some issues.\r\n\r\nTo make a long story short, we were finally able to get the\r\nfiles moved to the new server.  The site is now up and running.\r\nAgain, sorry for the long downtime.\r\n\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 4270, 5229, '2', '2016-05-25 20:15:03'),
(48, '{FIRSTNAME}, Test Email Please Disregard', '{FIRSTNAME}, Test Email Please Disregard', 'plain', 'all', 4390, 5220, '2', '2016-05-29 19:20:02'),
(49, '{FIRSTNAME}, Test Mail Please Delete', '{FIRSTNAME}, Test Mail Please Delete', 'plain', 'all', 4450, 5034, '2', '2016-05-31 07:43:33'),
(50, '{FIRSTNAME},  New Features Added to MCBT', 'Hi {FIRSTNAME},\r\n\r\nMike here.  First of all, we want to THANK YOU for being so patient during the testing\r\nof our traffic system.  We would also like to announce the following new features at MCBT.\r\n\r\n1)  ADD FREE BANNERS\r\n\r\nIn addition to 5 Free text ads, you can now add up to 5 banners to our system.\r\nYour text ads will continue rotate in the right-hand column of all of our main pages.\r\nYour banners will rotate underneath the sign up button on the main page, on the member\\\'s\r\nlogin page and underneath the member\\\'s Pay Stats table in the member\\\'s area.\r\n\r\nThese pages receive thousands of visitors each day.  So your text ads and banners will get\r\nmassive exposure.\r\n\r\nYour Text Ads and Banners will continue to rotate as long as you have at least 1 Active site\r\nwith at least 1 visitor credit assigned to that site on the \\\"Add Websites\\\" page OR 1 Active site\r\nwith at least 1 login credit assigned to that site on the \\\"Login Stats\\\" page.\r\n\r\n2)  NEW REFERRAL BANNERS & SPLASH PAGES\r\n\r\nWe have added splash pages and more banners.  In the member\\\'s area, click on the\r\n\\\"Affiliates\\\" button then click on the \\\"Affiliate Url\\\'s & Banners\\\" link from the drop-now\r\nmenu to see your splash pages and new banners.\r\n\r\n3)  VISITOR CREDITS ADDED TO YOUR ACCOUNT AUTOMATICALLY\r\n\r\nWe no longer have to add your visitor credits to your account manually.  When you purchase\r\nvisitor credits, they will be automatically added to your \\\"Unassigned Visitor Credits\\\" account\r\non the \\\"Add Websites\\\" page.\r\n\r\n4)  LOG IN ADS\r\n\r\nAs you know, we have added a login feature to the site.  This is an excellent way of getting\r\nREAL people to view your sites.  When members log in, they will view your site for 10\r\nseconds.  For details on purchasing Login Credits, click on the \\\"Buy Units\\\" button in your\r\nmember\\\'s area and then click on the \\\"Buy Login Credits\\\" link from the drop-down menu.\r\n\r\n5)   MYFREEVISITORS.COM\r\n\r\nWe have added a money-making feature to our site MyFreeVisitors.com.  Not only can you\r\nget Free traffic, you can also earn $25.00 each time a member in your downline upgrades.  For\r\nmore details, click on the link below.\r\n<a href=\\\"http://www.myfreevisitors.com\\\">Check Out MyFreeVisitors.com</a>\r\n\r\nNote:  Our programmer is still doing some final touch up work.  But as of now, the site is fully\r\nfunctional.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 4742, 5085, '2', '2016-06-13 21:21:08'),
(51, '{FIRSTNAME},  IMPORTANT Info Regarding Payza', 'Hi {FIRSTNAME},\r\n\r\nMike here.  On Friday, we received the following email from Payza.\r\nBefore we let you know what\\\'s going on, please read the email\r\nfrom Payza.\r\n\r\n======================================\r\n\r\n\r\nHello,\r\n\r\nPlease note that due to the specific industry you are involved in, we are obliged to place a weekly reserve on your transaction volume. The reserve applied will be 10% of your weekly sales and will be released automatically after 6 months.\r\n\r\nPlease understand that reserves are put in place to ensure that your Payza account is protected from chargebacks and reversal requests as part of the risk mitigation procedure.\r\n\r\nRegards,\r\n\r\nMerchant Risk Analyst\r\nwww.Payza.com\r\n\r\n\r\n\r\nTicket Details\r\n---------------------------------\r\nTicket ID: GNR-613-67368\r\nSubject: Your Payza Account\r\n\r\n\r\nNeed more info? Search our FAQs for step-by-step instructions and detailed information: https://helpdesk.payza.com/index.php?\r\n\r\n\r\n======================================\r\n\r\nAfter reading this email we immediately replied to Payza requesting that\r\nthe limitation be removed from our account.  We explained to them\r\nin great detail how this limitation would negatively affect our business.\r\n\r\nIn their email, they wrote the following statement:  \\\"due to the specific\r\nindustry you are involved in\\\".  We asked them why are we being penalized\r\nfor being in a certain industry.  We understand that the revshare industry\r\ndoes incur a lot of charge backs due to members not getting paid.\r\n\r\nBut we asked, why not look at individual companies in the industry that\r\nare having problem with charge backs and deal with them accordingly.  \r\nWe asked them to check their records and they will see that we do not\r\nhave a problem with charge backs or reversals.\r\n\r\nIn another statement they wrote: \\\"we are obliged to place a weekly reserve\r\non your transaction volume. The reserve applied will be 10% of your weekly\r\nsales and will be released automatically after 6 months.\\\"\r\n\r\nOur weekly Payza sales are averaging about $172,000 a week.  There is\r\nno way we can continue to payout at 200% when they are placing 10%\r\nof our weekly sales in reserve.\r\n\r\nSo at the moment, we are waiting on Payza\\\'s response.  Since Payza has\r\nplaced this limitation on our account, we have no choice but to reduce the\r\ncash back rate.  Effective the 20th of June, the cash back rate will be reduced\r\nfrom 200% to 150%.\r\n\r\nAll units purchased prior to the 20th of June, will be entered in the\r\ndatabase at the cash back rate of 200%. But when you are actually paid on\r\nthe 20th of June, the purchase amount of your Expired units will be paid out at the\r\ncash back rate of 150%.\r\n\r\nAny new purchases after the 20th of June, will be entered in the database\r\nat 150% of the traffic unit purchase amount and all payouts in the future will\r\nbe paid out at the cash back rate of 150%.\r\n\r\nIf Payza replies back to us and tells us that they have removed the limitation from\r\nour account, then we will immediately raise the cash back rate back to 200%.\r\nWe will keep you informed of any updates we receive from Payza.\r\n\r\nIn the meantime, we are currently researching other payment processors\r\nsuch as Solid Trust Pay, Perfect Money and Bitcoins.  With or without\r\nPayza, we will be here paying you each and every month.\r\n\r\nWe want to reassure you that we are not going anywhere.  We have our hearts\r\nand souls in this business. We are helping too many people for us to just\r\nthrow our hands up in frustration and give up.  So don\\\'t worry.  This is just\r\na temporary setback.  Hang in there while we get this mess sorted out.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 4946, 5282, '2', '2016-06-19 05:57:33'),
(52, '{FIRSTNAME},  Update From Payza on 24 Jun 16', 'Hi {FIRSTNAME},\r\n\r\nMike here.  On Friday, the 24th of June, we had a chat with one of\r\nPayza\\\'s risk managers and this is how he explained the weekly reserve\r\nto us:  In order for Payza to have sufficient funds for charge backs,\r\nVisa requires Payza to take a reserve from its\\\' merchants whose\r\nbusinesses are listed in the high risk category.\r\n\r\nThe reserve is 10% of our weekly sales.  The money is returned to\r\nour account balance 6 months after EACH weekly reserve is taken.\r\n\r\nFor example, money taken for reserve on the 21st of June, that money\r\nwill be returned to our account balance on the 21st of December.  Money\r\ntaken for reserve on the 28th of June, that money will be returned to our\r\naccount balance on the 28th of December and so on...\r\n\r\nThis means that we will always be under this limitation.\r\n\r\nIn Payza\\\'s initial email to us, they made it sound like all the money\r\ntaken for reserve will be returned to our account balance in 6 months.\r\nThat is is not the case.\r\n\r\nSince we will always be under Payza\\\'s limitation, members will not be\r\nreimbursed for the reduction in the cash back rate and the cash back rate\r\nwill remain at 150%.  Additionally, we cannot increase the maximum\r\nnumber of Active units.  The maximum number of Active units will\r\nremain at 500.\r\n\r\nWe have researched several processors and each has its\\\' own drawbacks.\r\nFor instance, Solid Trust Pay is not licensed to do business in all 50\r\nstates of the U.S.  Perfect Money does not accept members from the U.S.\r\nOther processors have a limit on how much money we can send and receive\r\neach month.\r\n\r\nBut there is some good news.  PayToo seems to have exactly what we need.\r\nBut they also have a weekly reserve and the reserve rate is based on a\r\ncompany\\\'s charge back rate.  Their reserve rate starts at 5% of a company\\\'s\r\nweekly sales.  The weekly reserve rate is the only drawback for PayToo.\r\n\r\nWe are also looking at Bitcoin.  This is actually a perfect payment method.\r\nThe only drawback is figuring out how to do Mass Pay on the 20th of the\r\nmonth.  Our programmer is researching this issue for us.\r\n\r\nSo the search for a new processor continues.  We will also keep you informed\r\non any updates from Payza and any updates on a new processor.\r\n\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 5143, 5581, '2', '2016-06-26 14:30:19'),
(53, '{FIRSTNAME},  An Update From Payza 20 July 16', 'Hi {FIRSTNAME},\r\n\r\nMike here.  About a week ago, we sent Payza an email requesting that if they could not\r\nremove the 10% weekly reserve completely, we asked if they would they consider lowering \r\nthe reserve rate to 5%.\r\n\r\nOn Monday, the 18th of July, we received the following email reply from Michael Forde of\r\nPayza\\\'s risk management department.  Please please read his email below.\r\n\r\n====================================================================\r\n\r\n\r\n\r\n> On 7/18/2016 3:48 AM, Michael Forde wrote:\r\n>>\r\n>> Hey Mike,\r\n>>\r\n>>  \r\n>>\r\n>> Because your weekly reserve only started a few weeks ago, you’ll have to wait a few more months for us to reassess your account.  The good news is that if everything looks good at that point, we may be able to consider reducing your weekly reserve to 5% instead of 10%.\r\n>>\r\n>>  \r\n>>\r\n>> Please contact us again in a few months so we can reassess the reserves on your account.\r\n>>\r\n>>  \r\n>>\r\n>> Regards,\r\n>>\r\n>>  \r\n>>\r\n>> Michael\r\n>>\r\n>> Account Manager\r\n\r\n\r\n\r\n====================================================================\r\n\r\n\r\nHaving the reserve rate reduced to 5% is certainly good news and will definitely help our cash\r\nflow.  If we had just half of the money Payza has taken so far, we would have no problem paying\r\nout at the 150% cash back rate.  But the 10% reserve rate is still affecting our cash flow and our\r\nability to pay out at the 150% rate.   Since we cannot pay you at the 150% cash back rate, here\r\nis what we have planned:\r\n\r\n1)  On payday the 20th of July, we will pay you 72% of your Total Cash Earned.  This is equal to\r\na 108% cash back rate.  NOTE:  You are NOT LOSING the money you used to buy traffic units.  \r\nYou are just earning less in regards to your cash back earnings.\r\n\r\n2)  Effective the 22nd of July, the cash back rate will be reduced to 110%.  NOTE:  This rate will\r\nwill eventually increase.  Please keep reading.\r\n\r\n3)  Starting the 18th of December and each week thereafter, Payza will start adding money back\r\nto our account balance.  If Payza reduces the reserve rate to 5% and with money being added back\r\nto our account balance each week, this will definitely improve our cash flow.  We will then need to wait a\r\ncouple of paydays to determine how much we can raise the cash back rate.  Our goal is to\r\nget back to at least the 150% cash back rate.\r\n\r\nIf Payza does not reduce the reserve rate to 5%, we are hoping that the money added to our account\r\nbalance each week will allow us to increase the cash back rate to a decent percentage.\r\n\r\nWe do not like these constant changes either.  But these changes are necessary in order to ensure\r\nthe longevity and sustainability of our program.  This will be a process and will take some time.\r\nOnce Payza starts adding the money back to our account balance and if Payza reduces the reserve rate\r\nto 5%, we are confident that we can get back to at least the 150% cash back rate.  \r\n\r\n4)  We are still searching the internet for a processor that has all we need. So far, the processors\r\nwe have looked at have some major draw backs.  Specifically, these processors have limitations on\r\nhow much we can send and receive each month.  But we will continue our search.  As usual, we\r\nwill keep you updated on the search for a new processor and keep you updated on any new developments\r\nfrom Payza.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.mycashbacktraffic.com\\\">Click Here To Log Into Your Account</a>', 'plain', 'all', 5543, 10864, '2', '2016-07-20 02:51:19'),
(54, '{FIRSTNAME},  An Update To Our Term of Service', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to let you know we have made changes to our\r\nTerm of Service.  The changes were made to paragraph# 10.  Please <a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a>\r\nto read paragraph# 10 of our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 5544, 12819, '2', '2016-07-24 12:57:38');
INSERT INTO `url_mail_schedule` (`id`, `subject`, `description`, `mail_type`, `user_status`, `assigned`, `delivered`, `status`, `s_time`) VALUES
(55, '{FIRSTNAME},  An Update From Payza & Term of Service Change', 'Hi {FIRSTNAME},\r\n\r\nMike here.  On Thursday, the 28th of July, we received the following email\r\nreply from Michael Forde of Payza\\\'s risk management department.  Please\r\nread his email below.\r\n\r\n====================================================================\r\n\r\n\r\nOn 7/28/2016 3:05 AM, Michael Forde wrote:\r\n>\r\n> Hey Mike,\r\n>\r\n>  \r\n>\r\n> I know we were negotiating a reserve rate of 5%, however given your recent business model updates, we’ve decided to keep the reserves at 10%.\r\n>\r\n>  \r\n>\r\n> You can allow your new business model to establish itself over the course of 6 months and contact us again for a reassessment of your reserve rate.\r\n>\r\n>  \r\n>\r\n> Regards,\r\n>\r\n>  \r\n>\r\n> Mike\r\n>\r\n> Account Manager\r\n>\r\n> Payza.com\r\n>\r\n>  \r\n \r\n\r\n====================================================================\r\n\r\n1)  Even though this is not good news, we do have some good news to look\r\nforward to.  Starting the 18th of December, Payza will start adding money\r\nback to our account and this will definitely improve our cash flow.  \r\n\r\nSo here is what we have planned going forward.  The cash back rate will\r\nremain at 110%.  Once Payza starts adding money back to our account, we\r\nwill take a look at our cash flow and determine how much we can raise the\r\ncash back rate.\r\n\r\nGetting back to a cash back rate of 150% will be a process and a challenge.\r\nOur goal is to give you a cash back rate that is reasonable for you and\r\nsustainable for MCBT.  How much will we be able to raise the cash back rate?\r\n\r\nWe do not know.  It all depends on our sales and the amount of money Payza\r\nadds back to our account starting in December.\r\n\r\nWe know our business model works.  The problem has been Payza\\\'s 10% reserve\r\nrule. We want to reassure you that we are not going anywhere. If you stick\r\nwith us, together we will get back on track.\r\n\r\n2)  Currently, our search for a new processor is not going well.  Below are the 4\r\nthings a processor must offer in order for us to change processors:\r\n\r\n- We must be able to send at least $500,000 per month for payouts.\r\n\r\n- The processor must not impose a reserve of any kind.\r\n\r\n- Members of all 50 states of the U.S. must be allowed to join.\r\n\r\n- And the processor must have a Mass Pay feature.\r\n\r\nAll the processors we have looked at so far are missing at least 1 of these\r\nrequirements.  So if you guys come across a payment processor that meets\r\nthe 4 requirements above, please let us know.\r\n\r\n3)  We have made changes to paragraph# 6 of our Term of Service. \r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Please Click Here To Read Paragraph# 6</a>\r\n\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 2932, 5687, '2', '2016-07-31 16:53:33'),
(56, '{FIRSTNAME}, Payout For the 20th of August', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Before we tell you what is going on, let us tell\r\nyou how we are able to pay you 110% cash back.   When you \r\npurchase Traffic Units, Visitor Credits or Login Credits, \r\nwe use that money to purchase large volumes of traffic at \r\ndiscount prices. \r\n\r\nThat traffic is sold to customers on our other traffic networks. \r\nSome of the profits we make from our other traffic networks are \r\nused to pay you 110% cash back. \r\n\r\nIn the past 30 days, we have lost a lot of members.  Because we \r\nhave lost so many members, our sales for the past 30 days was only \r\n11% of the payroll for the 20th of August. \r\n\r\nWith sales being only 11% of the payroll for the 20th of August\r\nand Payza taking 10% of our weekly sales, on the 20th of August,\r\nyou will only be paid 11% of your Total Cash Earned.\r\n\r\nThe remaining 89% will be added back to your account and payable\r\non the 20th of next month.  \r\n\r\nPlease understand that our ability to pay you 110% cash back \r\ndepends on our sales for the previous 30 days. Most members are\r\nonly purchasing 3 units.  We understand that.  \r\n\r\nBut in order for us to payout 110% or more, sales have to be greater \r\nthan or equal to the payroll for the 20th of the month. \r\n\r\nThe bottom line is this:  \r\n\r\nWe need the sale of Traffic Units, Visitor Credits and Login Credits \r\nto pick up.  This is the only way our program will survive.  If sales \r\ndo not pick up, trying to pay 110% will always be a challenge.\r\n\r\nThere is some good news ahead.  In December, Payza will start adding\r\nmoney back to our account balance and this will definitely help our \r\ncash flow.  \r\n\r\nFinally, it is IMPORTANT that you understand how we are able to pay \r\nyou cash back.  Only you as members can make or break this program.  \r\nHow long this program lasts is all up to you.\r\n \r\nSincerely,\r\n\r\nMike', 'plain', 'all', 2654, 2655, '2', '2016-08-20 01:24:45'),
(57, '{FIRSTNAME}, Please Hold ALL Emails', 'Hi {FIRSTNAME},\r\n\r\nMike here.  We have been swamped with hundreds of emails.\r\nMost of the questions members asked were answered in the \r\nemail we sent to all members on the 20th of August.  \r\n\r\nIf you did not receive the email sent to all members on the\r\n20th of August, you can read that email below.\r\n\r\nAlso, MCBT will be taking a mental break for about 2\r\nweeks.  We will have an admin assistant working for about\r\n2 hours a day.  So the response to your emails will\r\nbe slow.\r\n\r\nPlease only send email that require immediate attention.\r\nEmails that do not require immediate attention will be\r\nanswered last.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n\r\n\r\n==================================================\r\nEMAIL SENT TO ALL MEMBERS ON THE 20TH OF AUGUST\r\n==================================================\r\n\r\n\r\n\r\n{FIRSTNAME}, Payout For the 20th of August\r\n\r\n\r\n\r\nHi {FIRSTNAME},\r\n\r\nMike here.  Before we tell you what is going on, let us tell\r\nyou how we are able to pay you 110% cash back.   When you \r\npurchase Traffic Units, Visitor Credits or Login Credits, \r\nwe use that money to purchase large volumes of traffic at \r\ndiscount prices. \r\n\r\nThat traffic is sold to customers on our other traffic networks. \r\nSome of the profits we make from our other traffic networks are \r\nused to pay you 110% cash back. \r\n\r\nIn the past 30 days, we have lost a lot of members.  Because we \r\nhave lost so many members, our sales for the past 30 days was only \r\n11% of the payroll for the 20th of August. \r\n\r\nWith sales being only 11% of the payroll for the 20th of August\r\nand Payza taking 10% of our weekly sales, on the 20th of August,\r\nyou will only be paid 11% of your Total Cash Earned.\r\n\r\nThe remaining 89% will be added back to your account and payable\r\non the 20th of next month.  \r\n\r\nPlease understand that our ability to pay you 110% cash back \r\ndepends on our sales for the previous 30 days. Most members are\r\nonly purchasing 3 units.  We understand that.  \r\n\r\nBut in order for us to payout 110% or more, sales have to be greater \r\nthan or equal to the payroll for the 20th of the month. \r\n\r\nThe bottom line is this:  \r\n\r\nWe need the sale of Traffic Units, Visitor Credits and Login Credits \r\nto pick up.  This is the only way our program will survive.  If sales \r\ndo not pick up, trying to pay 110% will always be a challenge.\r\n\r\nThere is some good news ahead.  In December, Payza will start adding\r\nmoney back to our account balance and this will definitely help our \r\ncash flow.  \r\n\r\nFinally, it is IMPORTANT that you understand how we are able to pay \r\nyou cash back.  Only you as members can make or break this program.  \r\nHow long this program lasts is all up to you.\r\n \r\nSincerely,\r\n\r\nMike', 'plain', 'all', 2610, 2610, '2', '2016-08-22 12:13:00'),
(58, '{FIRSTNAME},  Payouts For The 20th of September', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were only 1% of the payout for the \r\n20th of September.  As a result, you will be paid 1% of your Total Cash\r\nEarned.  The remaining 99% will be added back to your account and payable \r\non the 20th of October.\r\n\r\n=====================\r\nVERY IMPORTANT\r\n=====================\r\n\r\nWe need the sale of Traffic Units, Visitor Credits and Login Credits to\r\npick up.  Members purchasing only 3 Traffic Units per month is not going to do\r\nit.  We need members to purchase like they did in March, April and May.  \r\nOtherwise, we will NEVER be able to pay you 100% of your Total Cash\r\nEarned.\r\n\r\nWe cannot continue to compound your Total Cash Earned as we are only digging \r\na deeper hole.  We will give this program a couple of more payouts.  If we are not \r\nable to pay you 100% of your Total Cash Earned by the 20th of November, we will \r\nhave to consider closing this program.\r\n\r\nOnly you as members can save this program.  All it takes is for you to purchase \r\nthe way you did in March, April and May and this program will be back on track.  \r\nIt\\\'s all up to you the members.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what \r\nhappens when we are not able to pay 100% of your Total Cash Earned, please \r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 1418, 1417, '2', '2016-09-20 00:56:06'),
(59, '{FIRSTNAME},  Please Read Our Term of Service', 'Hi {FIRSTNAME},\r\n\r\nMike here.  We get a lot of questions from members regarding our\r\nTerm of Service.  It\\\'s obvious that some members have never read\r\nour TOS.  So please take this time to read our TOS.  It\\\'s very important.\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 666, 666, '2', '2016-10-18 23:53:43'),
(60, '{FIRSTNAME},  Please Read Our Term of Service', 'Hi {FIRSTNAME},\r\n\r\nMike here.  We get a lot of questions from members regarding our\r\nTerm of Service.  It\\\'s obvious that some members have never read\r\nour TOS.  So please take this time to read our TOS.  It\\\'s very important.\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 666, 666, '2', '2016-10-19 00:24:22'),
(61, '{FIRSTNAME},  Payouts For The 20th of October', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were less than 1% of the payout for the \r\n20th of October.  As a result, there will be no payout on the 20th of October\r\nas there is not enough money in our Payza account to even pay most members $1.\r\nYour Total Cash Earned will be carried forward for the next payday.\r\n\r\nIf we are not able to pay members 100% of their Total Cash Earned on the\r\n20th of November, we will close the program, issue refunds to members\r\nthat are not in profit and relaunch the program.\r\n\r\nOn the 20th of November, we will send an email to all members detailing our\r\nexact plans.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what \r\nhappens when we are not able to pay 100% of your Total Cash Earned, please \r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 659, 659, '2', '2016-10-20 00:20:14'),
(62, '{FIRSTNAME},  Payouts For The 20th of November', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were less than 1% of the payout for the\r\n20th of November.  As a result, there will be no payout on the 20th of November.\r\n\r\nWe have decided to reorganize our program instead of closing down completely.  \r\nBelow is what will happen during our reorganization.  On the 20th of November, \r\nwe will temporarily stop selling Traffic Units.  But we will continue to \r\nsell Visitor Credits and Login Credits.\r\n\r\nBelow are the details of our plan.\r\n\r\n1)  In our Term of Service, it states no refunds are allowed. In this case,\r\nwe will make an exception.  ONLY MEMBERS WHO ARE NOT IN PROFIT\r\nWILL RECEIVE A REFUND.\r\n\r\nNote:  Your Net Income is computed as follows:  Your Total Payments\r\nReceived minus Your Total Traffic Units Purchased.\r\n\r\nTo determine whether you are in profit or not, log into your MCBT\r\naccount and click on the \\\"History\\\" link.  At the top of that page,\r\nyou will see your Net Income.  If your net income is $0.00, that means\r\nyou have broken even.  If your net income is greater than $0.00, that\r\nmeans you are in profit.  If your net income is less than $0.00, that\r\nmeans you are NOT in profit.\r\n\r\nFor members that are NOT in profit, your refund will be the amount of\r\nyour Net Income.  NOTE:  We will try to refund 100% of your Net Income.\r\nIn some cases, a partial refund will be issue or No Refund at all.  It just \r\ndepends on how much money is left in our Payza account at that time.\r\n\r\n2)  THIS IS HOW THE REFUND PROCESS WILL WORK:\r\n\r\nOn or about the 9th of January, Payza will start adding money back\r\nto our account on a weekly basis until all the money held in reserve\r\nis added back to our Payza account.  (Note:  We thought this process\r\nwould start in December, but it will start in January).\r\n\r\nEach week when Payza adds money back to our account, our system will\r\ngenerate a list of members that are NOT in profit.  We will start from\r\nthe top of that list and work our way down issuing refunds.  \r\n\r\nThis process will continue each week until all members that are NOT in \r\nprofit are issued refunds or when Payza has finish adding money back to \r\nour account and our account balance is $0.00.  Once our Payza account \r\nbalance is $0.00, there will be no money left for refunds.  So it is possible\r\nthat some members who are not in profit will not receive a refund at all.\r\n\r\n3)  Once the refund process is completed, we will delete all financial data\r\npertaining to member\\\'s accounts.  This includes the following data:\r\n\r\n- TRAFFIC UNIT PURCHASE HISTORY\r\n\r\n- AFFILIATE COMMISSIONS HISTORY\r\n\r\n- CASH ADJUSTMENT HISTORY\r\n\r\n- and the PAYMENT HISTORY\r\n\r\nNOTE:  Your account will NOT be deleted; only the financial data listed above\r\nwill be deleted from your account.\r\n\r\n4)  Once the above items are completed, we will relaunch the program.\r\n\r\nWe will start with a cash back rate of 110% and will gradually increase\r\nthis rate depending on sales.  We do not have a relaunch date yet.  But\r\nwe will send an email to all members once the relaunch date is set.  We believe\r\nthis is the fairest and right thing to do.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what\r\nhappens when we are not able to pay 100% of your Total Cash Earned, please\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 465, 472, '2', '2016-11-19 21:03:06'),
(63, '{FIRSTNAME},  Payouts For The 20th of November', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were less than 1% of the payout for the\r\n20th of November.  As a result, there will be no payout on the 20th of November.\r\n\r\nWe have decided to reorganize our program instead of closing down completely.  \r\nBelow is what will happen during our reorganization.  On the 20th of November, \r\nwe will temporarily stop selling Traffic Units.  But we will continue to \r\nsell Visitor Credits and Login Credits.\r\n\r\nBelow are the details of our plan.\r\n\r\n1)  In our Term of Service, it states no refunds are allowed. In this case,\r\nwe will make an exception.  ONLY MEMBERS WHO ARE NOT IN PROFIT\r\nWILL RECEIVE A REFUND.\r\n\r\nNote:  Your Net Income is computed as follows:  Your Total Payments\r\nReceived minus Your Total Traffic Units Purchased.\r\n\r\nTo determine whether you are in profit or not, log into your MCBT\r\naccount and click on the \\\"History\\\" link.  At the top of that page,\r\nyou will see your Net Income.  If your net income is $0.00, that means\r\nyou have broken even.  If your net income is greater than $0.00, that\r\nmeans you are in profit.  If your net income is less than $0.00, that\r\nmeans you are NOT in profit.\r\n\r\nFor members that are NOT in profit, your refund will be the amount of\r\nyour Net Income.  NOTE:  We will try to refund 100% of your Net Income.\r\nIn some cases, a partial refund will be issue or No Refund at all.  It just \r\ndepends on how much money is left in our Payza account at that time.\r\n\r\n2)  THIS IS HOW THE REFUND PROCESS WILL WORK:\r\n\r\nOn or about the 9th of January, Payza will start adding money back\r\nto our account on a weekly basis until all the money held in reserve\r\nis added back to our Payza account.  (Note:  We thought this process\r\nwould start in December, but it will start in January).\r\n\r\nEach week when Payza adds money back to our account, our system will\r\ngenerate a list of members that are NOT in profit.  We will start from\r\nthe top of that list and work our way down issuing refunds.  \r\n\r\nThis process will continue each week until all members that are NOT in \r\nprofit are issued refunds or when Payza has finish adding money back to \r\nour account and our account balance is $0.00.  Once our Payza account \r\nbalance is $0.00, there will be no money left for refunds.  So it is possible\r\nthat some members who are not in profit will not receive a refund at all.\r\n\r\n3)  Once the refund process is completed, we will delete all financial data\r\npertaining to member\\\'s accounts.  This includes the following data:\r\n\r\n- TRAFFIC UNIT PURCHASE HISTORY\r\n\r\n- AFFILIATE COMMISSIONS HISTORY\r\n\r\n- CASH ADJUSTMENT HISTORY\r\n\r\n- and the PAYMENT HISTORY\r\n\r\nNOTE:  Your account will NOT be deleted; only the financial data listed above\r\nwill be deleted from your account.\r\n\r\n4)  Once the above items are completed, we will relaunch the program.\r\n\r\nWe will start with a cash back rate of 110% and will gradually increase\r\nthis rate depending on sales.  We do not have a relaunch date yet.  But\r\nwe will send an email to all members once the relaunch date is set.  We believe\r\nthis is the fairest and right thing to do.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what\r\nhappens when we are not able to pay 100% of your Total Cash Earned, please\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 465, 472, '2', '2016-11-20 02:37:08'),
(64, '{FIRSTNAME},  Payouts For The 20th of November', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were less than 1% of the payout for the\r\n20th of November.  As a result, there will be no payout on the 20th of November.\r\n\r\nWe have decided to reorganize our program instead of closing down completely.  \r\nBelow is what will happen during our reorganization.  On the 20th of November, \r\nwe will temporarily stop selling Traffic Units.  But we will continue to \r\nsell Visitor Credits and Login Credits.\r\n\r\nBelow are the details of our plan.\r\n\r\n1)  In our Term of Service, it states no refunds are allowed. In this case,\r\nwe will make an exception.  ONLY MEMBERS WHO ARE NOT IN PROFIT\r\nWILL RECEIVE A REFUND.\r\n\r\nNote:  Your Net Income is computed as follows:  Your Total Payments\r\nReceived minus Your Total Traffic Units Purchased.\r\n\r\nTo determine whether you are in profit or not, log into your MCBT\r\naccount and click on the \\\"History\\\" link.  At the top of that page,\r\nyou will see your Net Income.  If your net income is $0.00, that means\r\nyou have broken even.  If your net income is greater than $0.00, that\r\nmeans you are in profit.  If your net income is less than $0.00, that\r\nmeans you are NOT in profit.\r\n\r\nFor members that are NOT in profit, your refund will be the amount of\r\nyour Net Income.  NOTE:  We will try to refund 100% of your Net Income.\r\nIn some cases, a partial refund will be issue or No Refund at all.  It just \r\ndepends on how much money is left in our Payza account at that time.\r\n\r\n2)  THIS IS HOW THE REFUND PROCESS WILL WORK:\r\n\r\nOn or about the 9th of January, Payza will start adding money back\r\nto our account on a weekly basis until all the money held in reserve\r\nis added back to our Payza account.  (Note:  We thought this process\r\nwould start in December, but it will start in January).\r\n\r\nEach week when Payza adds money back to our account, our system will\r\ngenerate a list of members that are NOT in profit.  We will start from\r\nthe top of that list and work our way down issuing refunds.  \r\n\r\nThis process will continue each week until all members that are NOT in \r\nprofit are issued refunds or when Payza has finish adding money back to \r\nour account and our account balance is $0.00.  Once our Payza account \r\nbalance is $0.00, there will be no money left for refunds.  So it is possible\r\nthat some members who are not in profit will not receive a refund at all.\r\n\r\n3)  Once the refund process is completed, we will delete all financial data\r\npertaining to member\\\'s accounts.  This includes the following data:\r\n\r\n- TRAFFIC UNIT PURCHASE HISTORY\r\n\r\n- AFFILIATE COMMISSIONS HISTORY\r\n\r\n- CASH ADJUSTMENT HISTORY\r\n\r\n- and the PAYMENT HISTORY\r\n\r\nNOTE:  Your account will NOT be deleted; only the financial data listed above\r\nwill be deleted from your account.\r\n\r\n4)  Once the above items are completed, we will relaunch the program.\r\n\r\nWe will start with a cash back rate of 110% and will gradually increase\r\nthis rate depending on sales.  We do not have a relaunch date yet.  But\r\nwe will send an email to all members once the relaunch date is set.  We believe\r\nthis is the fairest and right thing to do.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what\r\nhappens when we are not able to pay 100% of your Total Cash Earned, please\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 465, 471, '2', '2016-11-20 03:36:43'),
(65, '{FIRSTNAME},  Payouts For The 20th of November', 'Hi {FIRSTNAME},\r\n\r\nMike here.  Sales for the past 30 days were less than 1% of the payout for the\r\n20th of November.  As a result, there will be no payout on the 20th of November.\r\n\r\nWe have decided to reorganize our program instead of closing down completely.  \r\nBelow is what will happen during our reorganization.  On the 20th of November, \r\nwe will temporarily stop selling Traffic Units.  But we will continue to \r\nsell Visitor Credits and Login Credits.\r\n\r\nBelow are the details of our plan.\r\n\r\n1)  In our Term of Service, it states no refunds are allowed. In this case,\r\nwe will make an exception.  ONLY MEMBERS WHO ARE NOT IN PROFIT\r\nWILL RECEIVE A REFUND.\r\n\r\nNote:  Your Net Income is computed as follows:  Your Total Payments\r\nReceived minus Your Total Traffic Units Purchased.\r\n\r\nTo determine whether you are in profit or not, log into your MCBT\r\naccount and click on the \\\"History\\\" link.  At the top of that page,\r\nyou will see your Net Income.  If your net income is $0.00, that means\r\nyou have broken even.  If your net income is greater than $0.00, that\r\nmeans you are in profit.  If your net income is less than $0.00, that\r\nmeans you are NOT in profit.\r\n\r\nFor members that are NOT in profit, your refund will be the amount of\r\nyour Net Income.  NOTE:  We will try to refund 100% of your Net Income.\r\nIn some cases, a partial refund will be issue or No Refund at all.  It just \r\ndepends on how much money is left in our Payza account at that time.\r\n\r\n2)  THIS IS HOW THE REFUND PROCESS WILL WORK:\r\n\r\nOn or about the 9th of January, Payza will start adding money back\r\nto our account on a weekly basis until all the money held in reserve\r\nis added back to our Payza account.  (Note:  We thought this process\r\nwould start in December, but it will start in January).\r\n\r\nEach week when Payza adds money back to our account, our system will\r\ngenerate a list of members that are NOT in profit.  We will start from\r\nthe top of that list and work our way down issuing refunds.  \r\n\r\nThis process will continue each week until all members that are NOT in \r\nprofit are issued refunds or when Payza has finish adding money back to \r\nour account and our account balance is $0.00.  Once our Payza account \r\nbalance is $0.00, there will be no money left for refunds.  So it is possible\r\nthat some members who are not in profit will not receive a refund at all.\r\n\r\n3)  Once the refund process is completed, we will delete all financial data\r\npertaining to member\\\'s accounts.  This includes the following data:\r\n\r\n- TRAFFIC UNIT PURCHASE HISTORY\r\n\r\n- AFFILIATE COMMISSIONS HISTORY\r\n\r\n- CASH ADJUSTMENT HISTORY\r\n\r\n- and the PAYMENT HISTORY\r\n\r\nNOTE:  Your account will NOT be deleted; only the financial data listed above\r\nwill be deleted from your account.\r\n\r\n4)  Once the above items are completed, we will relaunch the program.\r\n\r\nWe will start with a cash back rate of 110% and will gradually increase\r\nthis rate depending on sales.  We do not have a relaunch date yet.  But\r\nwe will send an email to all members once the relaunch date is set.  We believe\r\nthis is the fairest and right thing to do.\r\n\r\nAlso, if you have questions on the changing of the Cash Back rate and what\r\nhappens when we are not able to pay 100% of your Total Cash Earned, please\r\n<a href=\\\"http://www.mycashbacktraffic.com/terms.php\\\">Click Here</a> to read our Term of Service.\r\n\r\nSincerely,\r\n\r\nMike', 'plain', 'all', 465, 471, '2', '2016-11-20 03:42:31'),
