(101, 'test Email', 'test Email\r\n\r\nPlease Ignore it\r\n\r\n\r\nThanks!', 'plain', 'L', 266, 266, '2', '2018-08-18 10:04:38'),
(102, '{FIRSTNAME}, Email Testing5, Please Disregard', 'Hi {FIRSTNAME}, Email Testing5, Please Disregard,\r\n\r\nMike here.  Just testing hyperlinks and the email body content for proper\r\nformat.  <a href=\\\"http://www.yahoo.com\\\">Test Hyperlink</a>\r\n\r\nThis website template has been designed by Free Website Templates for you, \r\nfor free. You can replace all this text with your own text. You can remove any \r\nlink to our website from this website template, you\\\'re free to use this website \r\ntemplate without linking back to us. If you\\\'re having problems editing this \r\nwebsite template, then don\\\'t hesitate to ask for help on the Forums.\r\n\r\nWant an easier solution for a Free Website? Head straight to Wix and immediately \r\nstart customizing your website! Wix is an online website builder with a simple drag \r\n& drop interface, meaning you do the work online and instantly publish to the web. \r\nNothing to download, nothing to upload.  \r\n\r\nAll Wix templates are fully customizable and free to use. Just pick one you like, \r\nclick Edit, and enter the online editor. Change, add, and remove items as you like. \r\nWix also offers a ton of free design elements right inside the editor, like images, \r\nicons, animation files, and interactive widgets. Publish your Free Website in minutes!\r\n\r\nTo Your Success,\r\n\r\n\r\nMike\r\nAdmin\r\nEZ-MoneyMaker.com', 'plain', 'all', 266, 266, '2', '2018-08-18 13:01:03'),
(103, '{FIRSTNAME}, Buy One Get One F.ree', 'Hi {FIRSTNAME},\r\n\r\nMike Borders here.  We are having a special on our traffic packages.\r\nPurchase ANY website traffic package and receive the same package absolutely\r\nfree.\r\n\r\nFor example, if you purchase 5,000 visitors, you\\\'ll get 5,000 visitors \r\nabsolutely free.  This special will end on Sunday, the 21st of Oct.  \r\nAlso, you can add up to 5 FREE text ads to our system.  For more details,\r\nclick on the link below.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=http://www.myguaranteedvisitors.com>http://www.myguaranteedvisitors.com</a>', 'plain', 'all', 346, 346, '2', '2018-10-14 13:40:22'),
(104, '{FIRSTNAME}, Get A FREE Pro Upgrade', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to tell you about our FREE Pro Upgrade promotion.\r\nWe will give you a FREE Pro Upgrade at EZ-MoneyMaker.com.  For more details,\r\nlog into your account and click on the \\\"Get A FREE Pro Upgrade\\\" link at the\r\ntop of the page.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 347, 347, '2', '2018-10-14 16:22:03'),
(105, '{FIRSTNAME}, Get A FREE Pro Upgrade', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to tell you about our FREE Pro Upgrade promotion.\r\nWe will give you a FREE Pro Upgrade at EZ-MoneyMaker.com.  For more details,\r\nlog into your account and click on the \\\"Get A FREE Pro Upgrade\\\" link at the\r\ntop of the page.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 397, 397, '2', '2018-11-28 16:44:41');
INSERT INTO `url_mail_schedule` (`id`, `subject`, `description`, `mail_type`, `user_status`, `assigned`, `delivered`, `status`, `s_time`) VALUES
(106, '%firstname%, IMPORTANT, Please Read', 'Hi %firstname%,\r\n\r\nMike here.  We are no longer able to accept PayPal.  PayPal has\r\nfrozen account as they feel our site is a multi-level marketing\r\nsite.  We tried to explain to them that our members are paid\r\non one level only, but they basically refused to even listen.\r\n\r\nThe good new is our programmer is currently working to\r\nimplement Solid Trust Pay as our new payment processor.\r\nSolid Trust Pay has been around for over 12 years and is a professional\r\nand reputable company.  We have worked with them in the past.\r\n\r\nSo if you would like to continue to make money with us, you\r\nwill need a Solid Trust Pay account.  To get a Free account,\r\nplease follow the steps below.\r\n\r\n1)  <a href=\\\"https://www.solidtrustpay.com\\\">Click Here</a> to sign up for a Free Solid Trust Pay account.\r\n\r\n2)  Once you have your Solid Trust Pay username, log into your\r\nEZ-MoneyMaker account, click on the \\\"Account Details\\\" link at\r\nthe top, enter your Solid Trust Pay username in the Solid Trust\r\nPay field and click the Submit button.\r\n\r\nIf you already have a Solid Trust Pay account, just do Step# 2\r\nabove.\r\n\r\nAlso, for those members who have an Active subscription\r\nfor the CB Money Page or the Referral Url Advertising, your\r\nCB Money Page will remain Active and we will continue\r\nto send visitors to your referral url until your current\r\nsubscription expires.  Your subscription will not renew\r\nas we are not able to accept PayPal payments.\r\n\r\nOnce our programmer has completed implementing\r\nthe Solid Trust Pay payment processor and once all\r\ntesting is completed, we will send an email to all\r\nmembers letting you know you can now purchase the\r\nUpgrade to Pro, CB Money Page, Referral Url Advertisement\r\nand Login Ad Credits.\r\n\r\nIf you have questions, comments or suggestions, write\r\nus back.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 450, 450, '2', '2019-01-12 13:37:28'),
(107, '{FIRSTNAME}, IMPORTANT Info Regard Solid Trust Pay', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to tell you about our new payment processor\r\nSolid Trust Pay.  We no longer accept PayPal as a payment processor.\r\nIf you would to continue to make money with us or purchase our services,\r\nyou will need a Solid Trust Pay account.\r\n\r\nTo get a free Solid Trust Pay account, please do the following:\r\n\r\n1)  <a href=\\\"https://www.solidtrustpay.com/leader_is/v21wka7u\\\">Click Here</a> to get your free Solid Trust Pay account.  Once you have your \r\nSolid Trust Pay username, you will need to do the following:\r\n\r\n2)  Log into your EZ-MoneyMaker account, Click on the \\\"Account Details\\\"\r\nlink at the top of the page and add your Solid Trust Pay username.\r\n\r\nIf you already have a Solid Trust Pay username, then do step# 2 only.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 450, 450, '2', '2019-01-20 12:43:40'),
(108, '{FIRSTNAME}, Solid Trust Pay is Now Live!', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to tell you that our programmer has finish adding\r\nSolid Trust Pay.  You can now purchase our services using Solid Trust Pay.\r\n\r\nIf you would like to continue to make money with us or purchase our services,\r\nyou will need a Solid Trust Pay account.\r\n\r\nTo get a free Solid Trust Pay account, please do the following:\r\n\r\n1)  <a href=\\\"https://www.solidtrustpay.com/leader_is/v21wka7u\\\">Click Here</a> to get your free Solid Trust Pay account.  Once you have your\r\nSolid Trust Pay username, you will need to do the following:\r\n\r\n2)  Log into your EZ-MoneyMaker account, Click on the \\\"Account Details\\\"\r\nlink at the top of the page and add your Solid Trust Pay username.\r\nIf you already have a Solid Trust Pay username, then do step# 2 only.\r\nIMPORTANT:  Make sure you add your Solid Trust Pay Username.  If one\r\nof your referrals upgrades to Pro, you will miss out on your commissions.\r\n\r\nIf you had a PayPal subscription to one of our services, that PayPal subscription\r\nhas been cancelled.  \r\n\r\nIf you would like to subscribe to one of our services, you will need to subscribe\r\nusing Solid Trust Pay.  Just log into your EZ-MoneyMaker account and click\r\non the \\\"Paid Services\\\" link at the top of the page.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 457, 457, '2', '2019-02-15 10:23:01'),
(109, '{FIRSTNAME}, You Can Now Use G Pay', 'Hi {FIRSTNAME},\r\n\r\nMike here. Just a short note to let you know that you can now use G Pay.\r\nG Pay is simple and easy.  All you need is a Gmail email address.\r\nIf you would like to continue to make money with us or purchase our services\r\nusing G Pay, Log into your EZ-MoneyMaker account, Click on the \\\"Account Details\\\" \r\nlink at the top of the page and add your Gmail email address.\r\n\r\nYour referrals can also pay you your commission via G Pay.  So make sure your \r\nG Pay email address is correct.  If one of your referrals upgrades to Pro, you will \r\nmiss out on your commissions.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 459, 459, '2', '2019-02-25 06:01:08'),
(110, '{FIRSTNAME}, Please Add A Gmail Email Address', 'Hi {FIRSTNAME},\r\n\r\nMike here. We just had 2 members upgrade to Pro using G Pay, but they couldn\\\'t pay\r\ntheir sponsors because their sponsors did not add a G Pay email address to their\r\nEZ-MoneyMaker account.\r\n\r\nWe had to manually pay both sponsors which was time consuming.  Effective\r\nimmediately, if one of your referrals upgrades via G Pay and you did not\r\nadd a G Pay email address to your EZ-MoneyMaker account, you will lose your\r\nsponsor fee as we will not manually send it to you.\r\n\r\nTo use G Pay, all you need is a gmail email address.  So as soon as you can,\r\nplease log into your EZ-MoneyMaker account, click on the \\\"Account Details\\\" link at\r\nthe top and add your G Pay email address.\r\n\r\nWe are not trying to be mean, it is just to much work trying to manually\r\npay members.\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 459, 459, '2', '2019-02-27 08:44:17'),
(111, '{FIRSTNAME}, New Payment Processor', 'Hi {FIRSTNAME},\r\n\r\nMike here. We will be adding a new payment processor called TransferWise.  \r\nOur programmer is in the process of integrating our script.\r\n\r\nTransferWise is super easy.  The only thing your referrals will need is your\r\nemail address.  Your referrals will send your sponsor fees directly \r\nto your bank account using only your email address. While our programmer \r\nis getting things ready, here is what you need to do:\r\n\r\n1)  <a href=\\\"https://transferwise.com/u/danr164\\\">Click Here</a> to sign up for a Free TransferWise account.  NOTE:  the\r\nemail address you use to sign up for a TransferWise account will be\r\nthe same email address you will add to your EZ-MoneyMaker.com\r\naccount.\r\n\r\n2)  Once our programmer has completed the integration,  I will send you\r\nan email letting you know you can now add your TransferWise email\r\naddress to your EZ-MoneyMaker account.  So go ahead and open your\r\nTransferWise account now!\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n<a href=\\\"http://www.ez-moneymaker.com\\\">Log Into Your Account</a>', 'plain', 'all', 492, 1459, '2', '2019-10-25 06:41:16'),
