(124, '{FIRSTNAME}, New Payment Processor and Free Pro Upgrade', 'Hi {FIRSTNAME},\r\n\r\nMike here. I have a couple of things to tell you.  First, Venmo is our new\r\npayment processor.  Venmo is free and the sign up process is quick and easy.  \r\nIf you need a Venmo account, <a href=\"https://www.venmo.com\">Click Here</a> to get one free.\r\n\r\nIn order to receive payments from your referrals, you will need to add your\r\nVenmo username to your EZ-MoneyMaker account.  To do so, log into your \r\nEZMM account and click on the \"Account Details\" link in the navigation bar.\r\n\r\nSecond, we are offering you a Free Pro Upgrade.  All you have to do is \r\npurchase Login Credits.  You must spend at least $30.  To purchase Login \r\nCredits, log into your EZMM account and click on the \"Buy Login Credits\"\r\nlink under the \"Paid Services\" tab.\r\n\r\nOnce we verify your order, we will upgrade your account to Pro ($50 value)\r\nand send you an email confirming that your account has been upgraded to \r\nPro.  This offer is valid for the next 3 days only.  So Order Now!\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n\r\n<a href=\"https://www.ez-moneymaker.com\">Log Into Your Account</a>\r\n\r\nYour Username is:  {USERID}\r\n\r\nYour Password is:  {PASSWORD}', 'html', 'all', 493, 492, '2', '2023-04-23 15:30:16'),
(125, '{FIRSTNAME}, New Payment Processor and Free Pro Upgrade', 'Hi {FIRSTNAME},\r\n\r\nMike here. I have a couple of things to tell you.  First, Venmo is our new payment processor.  Venmo is free and the sign-up process is quick and easy. If you need a Venmo account, <a href=\"https://www.venmo.com\">Click Here</a> to get one free.\r\n\r\nIn order to receive payments from your referrals, you will need to add your Venmo username to your EZ-MoneyMaker account.  To do so, log into your EZMM account and click on the \"Account Details\" link in the navigation bar.\r\n\r\nSecond, we are offering you a Free Pro Upgrade.  All you have to do is reply to this email with the phrase \"Please Upgrade Me To Pro.\"\r\n\r\nNOTE:  The first 100 members that reply to this email will get the free Pro Upgrade.  Once we give away 100 Free Pro Upgrades, this offer will expire.  So, don\'t delay!\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n\r\n<a href=\"https://www.ez-moneymaker.com\">Log Into Your Account</a>\r\n\r\nYour Username is:  {USERID}\r\n\r\nYour Password is:  {PASSWORD}', 'plain', 'all', 491, 491, '2', '2023-07-15 17:01:57'),
(126, '{FIRSTNAME}, New Payment Processor and Free Pro Upgrade', 'Hi {FIRSTNAME},\r\n\r\nMike here. I have a couple of things to tell you.  First, Venmo is our new\r\npayment processor.  Venmo is free and the sign-up process is quick and easy.  \r\nIf you need a Venmo account, <a href=\"https://www.venmo.com\">Click Here</a> to get one free.\r\n\r\nIn order to receive payments from your referrals, you will need to add your\r\nVenmo username to your EZ-MoneyMaker account.  To do so, log into your \r\nEZMM account and click on the \"Account Details\" link in the navigation bar.\r\n\r\nSecond, we are offering you a Free Pro Upgrade.  All you have to do is \r\nreply to this email with the phrase \"Please Upgrade Me To Pro.\"\r\n\r\nNOTE:  The first 100 members that reply to this email will get the free\r\nPro Upgrade.  Once we give away 100 Free Pro Upgrades, this offer will \r\nexpire.  So, don\'t delay!\r\n\r\nIf you have questions, comments or suggestions, write us back.\r\n\r\nSincerely,\r\n\r\nMike\r\n\r\n\r\n<a href=\"https://www.ez-moneymaker.com\">Log Into Your Account</a>\r\n\r\nYour Username is:  {USERID}\r\n\r\nYour Password is:  {PASSWORD}', 'html', 'all', 491, 491, '2', '2023-07-15 17:55:34'),
