INSERT INTO `url_merchants` (`id`, `merchant_name`, `merchant_form`, `status`) VALUES
(3, 'Login Credits-----', '<form action=\\\"https://www.paypal.com/cgi-bin/webscr\\\" method=\\\"post\\\" target=\\\"_top\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"cmd\\\" value=\\\"_xclick\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"username\\\" value=\\\"[username]\\\"/>\r\n<input name=\\\"custom\\\" type=\\\"hidden\\\" value=\\\"one1=[login_quantity]&two2=[login_item_name1]&three3=[user_id] &four4=([first_name] [last_name])&five5=[username]&six6=[amount]&seven7=[login_purchase_date]&eight8=[login_processor]&nine9=[login_payer_email]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"login_quantity1\\\" value=\\\"[login_quantity1]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"login_purchase_date\\\" value=\\\"[login_purchase_date]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"login_processor\\\" value=\\\"[login_processor]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"login_payer_email\\\" value=\\\"[login_payer_email]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"business\\\" value=\\\"[admin_email]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"item_name\\\" value=\\\"[login_item_name]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"item_number\\\" value=\\\"[login_quantity] [login_item_name1] for User ID: [user_id] ([first_name] [last_name])\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"amount\\\" value=\\\"[amount]\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"currency_code\\\" value=\\\"USD\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"return\\\" value=\\\"[login_return_url]\\\"/>\r\n<input name=\\\"notify_url\\\" value=\\\"http://www.ez-moneymaker.com/notify_ezmm.php\\\" type=\\\"hidden\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"rm\\\" value=\\\"2\\\"/>\r\n<input type=\\\"hidden\\\" name=\\\"cancel_return\\\" value= \\\"[login_cancel_url]\\\"/>\r\n<input type=\\\"image\" src=\\\"http://ez-moneymaker.com/images/paypal_ezmm.gif\\\" border=\\\"0\\\" name=\\\"submit\\\" alt=\\\"PayPal - The safer, easier way to pay online!\\\"/>\r\n</form>', 'active'),
(4, 'Login', '<form action=\"https://solidtrustpay.com/handle.php\" method=\"post\" target=\"_top\"/>\r\n	<input type=\"hidden\" name=\"testmode\" value=\"off\"> \r\n	<input type=\"hidden\" name=\"username\" value=\"[username]\"/>\r\n	<input name=\"user1\" type=\"hidden\" value=\"[login_quantity]\" />\r\n	<input name=\"user2\" type=\"hidden\" value=\"[login_item_name1]\" />\r\n	<input name=\"user3\" type=\"hidden\" value=\"[user_id] \" />\r\n	<input name=\"user4\" type=\"hidden\" value=\"([first_name] [last_name])\" />\r\n	<input name=\"user5\" type=\"hidden\" value=\"[username]\" />\r\n	<input name=\"user6\" type=\"hidden\" value=\"[amount]\" />\r\n	<input name=\"user7\" type=\"hidden\" value=\"[login_purchase_date]\" />\r\n	<input name=\"user8\" type=\"hidden\" value=\"[login_processor]\" />\r\n	<input name=\"user9\" type=\"hidden\" value=\"[login_payer_email]\" />\r\n\r\n\r\n\r\n<input name=\"user10\" type=\"hidden\" value=\"[buyer_stp_fromDB]\" />\r\n\r\n\r\n\r\n\r\n	<input type=\"hidden\" name=\"login_quantity1\" value=\"[login_quantity1]\"/>\r\n	<input type=\"hidden\" name=\"login_purchase_date\" value=\"[login_purchase_date]\"/>\r\n	<input type=\"hidden\" name=\"login_processor\" value=\"[login_processor]\"/>\r\n	<input type=\"hidden\" name=\"login_payer_email\" value=\"[login_payer_email]\"/>\r\n	<input type=\"hidden\" name=\"merchantAccount\" value=\"wespac\"> \r\n	<input type=\"hidden\" name=\"sci_name\" value=\"EZMM\"> \r\n	<input type=\"hidden\" name=\"item_id\" value=\"[login_quantity] Login Credits for User ID: [username] ( [first_name] [last_name] )\">\r\n	<input type=\"hidden\" name=\"item_name\" value=\"[login_item_name]\"/>\r\n	<input type=\"hidden\" name=\"item_number\" value=\"[login_quantity] [login_item_name1] for User ID: [user_id] ([first_name] [last_name])\"/>\r\n	<input type=\"hidden\" name=\"amount\" value=\"[amount]\"/>\r\n	<input type=\"hidden\" name=\"currency_code\" value=\"USD\"/>\r\n	<input type=\"hidden\" name=\"return_url\" value=\